"""Derive SkyyRebirth/build_skyyrebirth_0.3.2.py from SkyyRebirth/build_skyyrebirth_0.3.1.py (= the tools/deploy_set.py SET pin, GENERATED by
tools/rebirth_0_3_1_patch.py). rep(old, new) with asserted anchors; 0.3.1 stays untouched; its line endings are kept; every change is checked
at the end to prove nothing else changed.
Run:  python tools/rebirth_0_3_2_patch.py   then   python SkyyRebirth/build_skyyrebirth_0.3.2.py   (NO --deploy: coordinated deploy)
Test: python SkyyRebirth/test_skyyrebirth_0.3.2.py --dir tools/dev/scratch/<yours>/rb   (bare JVM, -Xverify:all, every new code path executed)

0.3.2 (2026-10-14) = ECONOMY ROUND econ39, the SkyyRebirth part - GEAR JOINS THE REBIRTH (Skyy 2026-10-14 ~13:45, about the queued round
"A SkyyRebirth update so a rebirth also resets lifelong tools and gear": "Run the queue"). THE WHOLE FEATURE STAYS OFF (rebirth.on=false):
  (1) "gear" IS THE 4TH PARTICIPANT: RbJournal.PARTS = skills, coins, bank, gear (JARS "SkyyGear 0.3.5+"). SkyyGear 0.3.5's
      rebirth:part:gear (GearRb; contract in tools/gear_0_3_5_patch.py item 5: measure / prepare / commit / abort / status with the same
      Object[] { op, pkey, txid, Integer newN, rewards } -> String as Skills / Coins / Bank) now runs in every rebirth: prepare = a backup
      of lifelong/<pkey>.properties + the staged file, commit = ONE atomic write of its rebirth record (the world thread then puts every
      lifelong tool back to Crude, removes the Upgrade Points, moves Mining armor back to Copper - SkyyGear's own code). Nothing else in
      the coordinator changes: the journal records the parts list in its BEGIN line, so a journal opened by 0.3.1 (skills,coins,bank)
      is recovered with ITS three parts and a 0.3.2 journal with four. The requirement line / "Needs SkyyGear 0.3.5+" / the dry run /
      status count 4 parts; /rebirthadmin backups lists Skyy_SkyyGear/rebirth-backup too. Classes and trees stay OUT of PARTS (they
      wait for the modifier slot every 5th rebirth - docs/answered + tools/deploy_set.py note).
  (2) TOOL NODE NAMES MATCH: SkyyGear 0.3.5 reads rebirth:fn:node(UUID, "<Arm>.tool") + "<Arm>.tool2" for Mining (pickaxe + Multitool),
      Foraging (hatchet), Farming (hoe AND sickle) and Fishing (pole) - exactly the ids this tree sells ("Mining.tool", "Mining.tool2",
      ...; checked end to end in the harness with the REAL SkyyGear GearLL.rbNode). The node panel's "Works" line now says the
      Mining / Foraging / Farming tool nodes work NOW (SkyyGear multiplies Power, Fortune and Wisdom by the node levels x
      lifelong.rebirthPct); the Fishing ones wait for pole perks (SkyyGear draws no pole stats yet).
  (3) TEXTS name the tools AND the Mining armor (fix round, design critic 1: SkyyGear 0.3.5 also moves identified Mining armor back to
      Copper - docs/answered/gear.md 2026-10-12 "reset to T1 on rebirth"): the done line in chat ("... your lifelong tools are Crude
      again (upgrade points gone) and your Mining armor is Copper again"), the two armed notes on /rebirth, /rebirthadmin help and the
      rebirth / crashtest confirm, the ready line and the manifest.
  Every rebirth participant contract is unchanged; no saved-data change in SkyyRebirth's own files.
  DEPLOY: needs SkyyGear 0.3.5+ (already live) - without it every rebirth is refused at the click ("Rebirth needs SkyyGear 0.3.5+").
  ROLLBACK to 0.3.1: safe once no journal is open (0.3.1 recovers a 4-part journal with the parts its BEGIN line names - it would wait
  for "gear" because its JARS table lacks it: finish or recover every open rebirth BEFORE rolling back; /rebirthadmin status).
"""
import difflib
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
src = os.path.join(ROOT, "SkyyRebirth", "build_skyyrebirth_0.3.1.py")
dst = os.path.join(ROOT, "SkyyRebirth", "build_skyyrebirth_0.3.2.py")
raw = open(src, "rb").read()
NL = "\r\n" if b"\r\n" in raw else "\n"
assert NL == "\n" or raw.count(b"\r\n") == raw.count(b"\n"), "mixed line endings in 0.3.1"
s = raw.decode("utf8").replace("\r\n", "\n")
LF = "\n"
S0 = s
assert 'VERSION = "0.3.1"' in s and "GENERATED by tools/rebirth_0_3_1_patch.py" in s and '"SkyyGear 0.3.5+"' not in s, "not the generated 0.3.1"
OLDS = []


def rep(old, new, count=1):
    global s
    n = s.count(old)
    assert n == count, "anchor count %d (want %d): %s" % (n, count, old[:160])
    s = s.replace(old, new)
    OLDS.append(old)


HEAD = open(__file__, encoding="utf8").read().split('"""')[1]
NOTE = HEAD[HEAD.index("0.3.2 (2026-10-14)"):].rstrip() + "\n"

# ---------------------------------------------------------------- docstring + version
rep('''"""SkyyRebirth 0.3.1 - build script (javassist via jpype). GENERATED by tools/rebirth_0_3_1_patch.py from build_skyyrebirth_0.3.py (itself
generated by tools/rebirth_0_3_patch.py from 0.2,''',
    '''"""SkyyRebirth 0.3.2 - build script (javassist via jpype). GENERATED by tools/rebirth_0_3_2_patch.py from build_skyyrebirth_0.3.1.py (itself
generated by tools/rebirth_0_3_1_patch.py from 0.3, generated by tools/rebirth_0_3_patch.py from 0.2,''')
rep('''Run:   python SkyyRebirth/build_skyyrebirth_0.3.1.py   -> SkyyRebirth/SkyyRebirth-0.3.1.jar   (no --deploy: tools/deploy_set.py installs the set)
Check: python SkyyRebirth/test_skyyrebirth_0.3.1.py --dir tools/dev/scratch/<yours>/rb   (bare JVM, -Xverify:all, every code path executed)
''', '''Run:   python SkyyRebirth/build_skyyrebirth_0.3.2.py   -> SkyyRebirth/SkyyRebirth-0.3.2.jar   (no --deploy: tools/deploy_set.py installs the set)
Check: python SkyyRebirth/test_skyyrebirth_0.3.2.py --dir tools/dev/scratch/<yours>/rb   (bare JVM, -Xverify:all, every code path executed)

''' + NOTE + '''  CHECKED: SkyyRebirth/test_skyyrebirth_0.3.2.py.
''')
rep('VERSION = "0.3.1"\n', 'VERSION = "0.3.2"\n')

# ---------------------------------------------------------------- (1) the 4th participant
rep('''          'public static final String[] PARTS = new String[] { "skills", "coins", "bank" };',
          'public static final String[] JARS = new String[] { "SkyySkills 0.4.36+", "SkyyCoins 0.1.7+", "SkyyBank 0.1.11+" };',''',
    '''          'public static final String[] PARTS = new String[] { "skills", "coins", "bank", "gear" };',   # 0.3.2: + SkyyGear (classes / trees: later)
          'public static final String[] JARS = new String[] { "SkyySkills 0.4.36+", "SkyyCoins 0.1.7+", "SkyyBank 0.1.11+", "SkyyGear 0.3.5+" };',''')
rep('''  String[] ms = new String[] { "Skyy_SkyySkills", "Skyy_SkyyCoins", "Skyy_SkyyBank" };''',
    '''  String[] ms = new String[] { "Skyy_SkyySkills", "Skyy_SkyyCoins", "Skyy_SkyyBank", "Skyy_SkyyGear" };   // 0.3.2: + gear''')
rep('''                           "NO  Needs SkyyCoins 0.1.7+", "NO  Needs SkyyBank 0.1.11+", "NO  A rebirth is finishing",''',
    '''                           "NO  Needs SkyyCoins 0.1.7+", "NO  Needs SkyyBank 0.1.11+", "NO  A rebirth is finishing",
                           "NO  Needs SkyyGear 0.3.5+",   # 0.3.2''')

# ---------------------------------------------------------------- (2) the tool nodes' "Works" line
rep('''                                   "+{v} rebirth modifier levels on your %s" % TOOL[nm][1], "when SkyyGear gives tools their rebirth modifier", 7)''',
    '''                                   "+{v} rebirth modifier levels on your %s" % TOOL[nm][1],
                                   # 0.3.2: SkyyGear 0.3.5 reads "<Arm>.tool" / "<Arm>.tool2" (GearLL.rbNode); the pole has no stats yet
                                   "after a later Fishing update (pole perks)" if nm == "Fishing" else "now (SkyyGear: Power, Fortune and Wisdom)", 7)''')

# ---------------------------------------------------------------- (3) texts
rep('''". Your skills, purse and bank start again; the bank pays you +"''',
    '''". Your skills, purse and bank start again, your lifelong tools are Crude again (upgrade points gone) and your Mining armor is Copper again; the bank pays you +"''')
rep('''                            "Resets skills, purse and bank to 0! Press again within 10 s.",
                            "Closes orders (fees kept), resets skills, purse, bank! Press again.",   # 0.3 Continue armed''',
    '''                            "Resets skills, coins, tools, Mining armor! Press again in 10 s.",   # 0.3.2: + tools + armor
                            "Closes orders (fees kept), resets skills, coins, gear! Press again.",   # 0.3 Continue armed (0.3.2: gear = tools + Mining armor; 2 lines max)''')
rep('''  if (armed) this.note = this.goKind == 2 ? "Closes orders (fees kept), resets skills, purse, bank! Press again." : "Resets skills, purse and bank to 0! Press again within 10 s.";''',
    '''  if (armed) this.note = this.goKind == 2 ? "Closes orders (fees kept), resets skills, coins, gear! Press again." : "Resets skills, coins, tools, Mining armor! Press again in 10 s.";   // 0.3.2: tools + Mining armor''')
rep('''reset YOUR active profile's skills (not Exploration), purse and bank - type it twice within 10 s.''',
    '''reset YOUR active profile's skills (not Exploration), purse, bank, lifelong tools (back to Crude) and Mining armor (back to Copper) - type it twice within 10 s.''')
rep('''" resets YOUR active profile's skills (not Exploration), purse and bank (admin: class / place / combat checks skipped).''',
    '''" resets YOUR active profile's skills (not Exploration), purse, bank, lifelong tools (back to Crude) and Mining armor (back to Copper) (admin: class / place / combat checks skipped).''')
rep('''" (skills, coins, bank; Continue closes Bazaar / AH orders through "''', '''" (skills, coins, bank, gear; Continue closes Bazaar / AH orders through "''')
rep('''+3 % stats per rebirth for the mods that apply it. Server Setup: Rebirth. Zero dependencies.",''',
    '''+3 % stats per rebirth for the mods that apply it. 0.3.2: SkyyGear 0.3.5+ joins the rebirth (lifelong tools back to Crude, their upgrade points gone, identified Mining armor back to Copper; the tool nodes raise Power, Fortune and Wisdom). Server Setup: Rebirth. Zero dependencies.",''')

# ---------------------------------------------------------------- checks
assert s.count('"gear" };') == 1 and s.count('"SkyyGear 0.3.5+" };') == 1
_a, _b = S0.split(LF), s.split(LF)
_hunks = [op for op in difflib.SequenceMatcher(None, _a, _b, autojunk=False).get_opcodes() if op[0] != "equal"]
_gone = [(i, _a[i]) for op in _hunks for i in range(op[1], op[2])]
_allowed = set()
for _o in OLDS:
    _allowed.update(_o.split(LF))
_bad = [(i, ln) for i, ln in _gone if ln not in _allowed and not any(_o in ln for _o in OLDS if LF not in _o)]
assert not _bad, "0.3.1 lines changed outside the planned places: %r" % _bad[:5]
if os.path.exists(dst):
    os.remove(dst)
compile(s, dst, "exec")
open(dst, "wb").write(s.replace(LF, NL).encode("utf8"))
print("wrote", dst, len(s), "chars;", len(_hunks), "diff hunks vs 0.3.1,", len(_gone), "0.3.1 lines replaced;", len(OLDS), "anchors")
